// swift-tools-version: 5.8
import PackageDescription

let package = Package(
    name: "OpenMessageArchiveCore",
    platforms: [.macOS(.v13)],
    products: [
        .library(name: "OpenMessageArchiveCore", targets: ["OpenMessageArchiveCore"])
    ],
    targets: [
        .target(name: "OpenMessageArchiveCore"),
        .testTarget(
            name: "OpenMessageArchiveCoreTests",
            dependencies: ["OpenMessageArchiveCore"]
        )
    ]
)

import Foundation

public struct MessageArchive: Codable, Equatable, Sendable {
    public var schemaVersion: Int
    public var conversation: Conversation
    public var exportedAt: Date
    public var messages: [ArchivedMessage]

    public init(
        schemaVersion: Int = 1,
        conversation: Conversation,
        exportedAt: Date = Date(),
        messages: [ArchivedMessage]
    ) {
        self.schemaVersion = schemaVersion
        self.conversation = conversation
        self.exportedAt = exportedAt
        self.messages = messages
    }
}

public struct Conversation: Codable, Equatable, Sendable {
    public var id: String?
    public var displayName: String
    public var participants: [String]

    public init(id: String? = nil, displayName: String, participants: [String] = []) {
        self.id = id
        self.displayName = displayName
        self.participants = participants
    }
}

public enum MessageDirection: String, Codable, Sendable {
    case incoming
    case outgoing
    case unknown
}

public struct ArchivedMessage: Codable, Equatable, Sendable {
    public var id: String?
    public var date: Date
    public var sender: String?
    public var direction: MessageDirection
    public var body: String
    public var attachments: [ArchiveAttachment]

    public init(
        id: String? = nil,
        date: Date,
        sender: String? = nil,
        direction: MessageDirection = .unknown,
        body: String,
        attachments: [ArchiveAttachment] = []
    ) {
        self.id = id
        self.date = date
        self.sender = sender
        self.direction = direction
        self.body = body
        self.attachments = attachments
    }
}

public struct ArchiveAttachment: Codable, Equatable, Sendable {
    public var filename: String
    public var relativePath: String?
    public var mediaType: String?

    public init(filename: String, relativePath: String? = nil, mediaType: String? = nil) {
        self.filename = filename
        self.relativePath = relativePath
        self.mediaType = mediaType
    }
}

import Foundation

public enum ArchiveCodec {
    public static func encode(_ archive: MessageArchive, pretty: Bool = true) throws -> Data {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        if pretty {
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
        }
        return try encoder.encode(archive)
    }

    public static func decode(_ data: Data) throws -> MessageArchive {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try decoder.decode(MessageArchive.self, from: data)
    }
}

enum ArchiveEscaping {
    static func csv(_ value: String) -> String {
        if value.contains(",") || value.contains(""") || value.contains("\n") || value.contains("\r") {
            return """ + value.replacingOccurrences(of: """, with: """") + """
        }
        return value
    }

    static func html(_ value: String) -> String {
        value
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: """, with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#39;")
    }
}

import Foundation

public enum ArchiveFormat: String, CaseIterable, Sendable {
    case text = "txt"
    case csv
    case html
    case json
}

public enum ArchiveExporter {
    public static func render(_ archive: MessageArchive, as format: ArchiveFormat) throws -> Data {
        switch format {
        case .json:
            return try ArchiveCodec.encode(archive)
        case .text:
            return Data(renderText(archive).utf8)
        case .csv:
            return Data(renderCSV(archive).utf8)
        case .html:
            return Data(renderHTML(archive).utf8)
        }
    }

    public static func renderText(_ archive: MessageArchive) -> String {
        let formatter = ISO8601DateFormatter()
        var lines = ["Conversation: \(archive.conversation.displayName)", ""]
        for message in archive.messages.sorted(by: { $0.date < $1.date }) {
            let sender = message.sender ?? (message.direction == .outgoing ? "Me" : "Unknown")
            lines.append("[\(formatter.string(from: message.date))] \(sender): \(message.body)")
            for attachment in message.attachments {
                lines.append("  [attachment: \(attachment.filename)]")
            }
        }
        return lines.joined(separator: "\n") + "\n"
    }

    public static func renderCSV(_ archive: MessageArchive) -> String {
        let formatter = ISO8601DateFormatter()
        var rows = ["date,sender,direction,body,attachments"]
        for message in archive.messages.sorted(by: { $0.date < $1.date }) {
            let attachments = message.attachments.map(\.filename).joined(separator: " | ")
            let fields = [
                formatter.string(from: message.date),
                message.sender ?? "",
                message.direction.rawValue,
                message.body,
                attachments
            ].map(ArchiveEscaping.csv)
            rows.append(fields.joined(separator: ","))
        }
        return rows.joined(separator: "\n") + "\n"
    }

    public static func renderHTML(_ archive: MessageArchive) -> String {
        let formatter = ISO8601DateFormatter()
        let title = ArchiveEscaping.html(archive.conversation.displayName)
        let rows = archive.messages.sorted(by: { $0.date < $1.date }).map { message in
            let sender = ArchiveEscaping.html(message.sender ?? (message.direction == .outgoing ? "Me" : "Unknown"))
            let body = ArchiveEscaping.html(message.body).replacingOccurrences(of: "\n", with: "<br>")
            let timestamp = ArchiveEscaping.html(formatter.string(from: message.date))
            let attachmentHTML = message.attachments.map {
                "<div class=\"attachment\">Attachment: \(ArchiveEscaping.html($0.filename))</div>"
            }.joined()
            return "<article class=\"message \(message.direction.rawValue)\"><header>\(sender) <time>\(timestamp)</time></header><div class=\"body\">\(body)</div>\(attachmentHTML)</article>"
        }.joined(separator: "\n")
        return """
        <!doctype html>
        <html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
        <title>\(title)</title>
        <style>
        body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;max-width:860px;margin:0 auto;padding:24px;background:#fff;color:#111}
        h1{font-size:1.5rem}.message{padding:12px 14px;margin:10px 0;border-radius:14px;background:#f2f2f7}
        .message.outgoing{margin-left:12%;background:#e7f1ff}.message.incoming{margin-right:12%}
        header{font-weight:600;font-size:.86rem}time{font-weight:400;color:#666;margin-left:.5rem}
        .body{white-space:normal;margin-top:4px;line-height:1.35}.attachment{font-size:.85rem;color:#666;margin-top:6px}
        @media print{body{max-width:none}.message{break-inside:avoid}}
        </style></head><body><h1>\(title)</h1>\(rows)</body></html>
        """
    }
}

import XCTest
@testable import OpenMessageArchiveCore

final class ExporterTests: XCTestCase {
    private func fixture() -> MessageArchive {
        let base = Date(timeIntervalSince1970: 1_700_000_000)
        return MessageArchive(
            conversation: Conversation(
                id: "chat-1",
                displayName: "Alex & Me",
                participants: ["Alex", "Me"]
            ),
            exportedAt: base,
            messages: [
                ArchivedMessage(
                    id: "m1",
                    date: base,
                    sender: "Alex",
                    direction: .incoming,
                    body: "Hi, <remember this> & keep it."
                ),
                ArchivedMessage(
                    id: "m2",
                    date: base.addingTimeInterval(10),
                    sender: "Me",
                    direction: .outgoing,
                    body: "I will, \"always\".\nSecond line.",
                    attachments: [ArchiveAttachment(filename: "photo.jpg")]
                )
            ]
        )
    }

    func testJSONRoundTrip() throws {
        let original = fixture()
        let data = try ArchiveCodec.encode(original)
        XCTAssertEqual(try ArchiveCodec.decode(data), original)
    }

    func testCSVQuotesSpecialCharacters() {
        let csv = ArchiveExporter.renderCSV(fixture())
        XCTAssertTrue(csv.contains("\"I will, \"\"always\"\"."))
        XCTAssertTrue(csv.contains("photo.jpg"))
    }

    func testHTMLEscapesMessageText() {
        let html = ArchiveExporter.renderHTML(fixture())
        XCTAssertTrue(html.contains("&lt;remember this&gt; &amp; keep it."))
        XCTAssertFalse(html.contains("<remember this>"))
    }

    func testTextIsChronological() {
        let text = ArchiveExporter.renderText(fixture())
        XCTAssertLessThan(text.range(of: "Alex: Hi")!.lowerBound, text.range(of: "Me: I will")!.lowerBound)
    }
}

import SwiftUI

@main
struct OpenMessageArchiveApp: App {
    var body: some Scene {
        WindowGroup {
            ContentView()
        }
    }
}

import SwiftUI
import UniformTypeIdentifiers
import OpenMessageArchiveCore

struct ContentView: View {
    @State private var archive: MessageArchive?
    @State private var importError: String?
    @State private var showingImporter = false

    var body: some View {
        NavigationStack {
            VStack(spacing: 18) {
                if let archive {
                    Text(archive.conversation.displayName)
                        .font(.title2.bold())
                    Text("\(archive.messages.count) messages")
                        .foregroundStyle(.secondary)
                    Text("The archive is local. Export formats are generated on this device.")
                        .multilineTextAlignment(.center)
                    ExportButtons(archive: archive)
                } else {
                    ContentUnavailableView(
                        "No Conversation Yet",
                        systemImage: "bubble.left.and.bubble.right",
                        description: Text("Import a canonical conversation archive from the companion Shortcut.")
                    )
                }

                Button("Import JSON Archive") { showingImporter = true }
                    .buttonStyle(.borderedProminent)

                if let importError {
                    Text(importError).foregroundStyle(.red).font(.footnote)
                }
            }
            .padding()
            .navigationTitle("Message Archive")
        }
        .fileImporter(isPresented: $showingImporter, allowedContentTypes: [.json]) { result in
            do {
                let url = try result.get()
                let accessing = url.startAccessingSecurityScopedResource()
                defer { if accessing { url.stopAccessingSecurityScopedResource() } }
                archive = try ArchiveCodec.decode(Data(contentsOf: url))
                importError = nil
            } catch {
                importError = error.localizedDescription
            }
        }
    }
}

private struct ExportButtons: View {
    let archive: MessageArchive

    var body: some View {
        ForEach(ArchiveFormat.allCases, id: \.rawValue) { format in
            if let file = try? TemporaryExport.make(archive, format: format) {
                ShareLink(item: file) {
                    Label("Export \(format.rawValue.uppercased())", systemImage: "square.and.arrow.up")
                }
            }
        }
    }
}

private enum TemporaryExport {
    static func make(_ archive: MessageArchive, format: ArchiveFormat) throws -> URL {
        let data = try ArchiveExporter.render(archive, as: format)
        let base = archive.conversation.displayName
            .replacingOccurrences(of: "/", with: "-")
            .replacingOccurrences(of: ":", with: "-")
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent(base)
            .appendingPathExtension(format.rawValue)
        try data.write(to: url, options: .atomic)
        return url
    }
}

import AppIntents
import Foundation
import UniformTypeIdentifiers
import OpenMessageArchiveCore

@available(iOS 26.0, *)
struct ImportConversationIntent: AppIntent {
    static var title: LocalizedStringResource = "Import Conversation Archive"
    static var description = IntentDescription("Import a local conversation archive created by the companion Shortcut.")
    static var openAppWhenRun: Bool { true }

    @Parameter(
        title: "Conversation Archive",
        supportedContentTypes: [.json]
    )
    var archiveFile: IntentFile

    static var parameterSummary: some ParameterSummary {
        Summary("Import \(.$archiveFile)")
    }

    func perform() async throws -> some IntentResult & ProvidesDialog {
        let archive = try ArchiveCodec.decode(archiveFile.data)
        let directory = try Self.inboxDirectory()
        let safeName = archive.conversation.displayName
            .replacingOccurrences(of: "/", with: "-")
            .replacingOccurrences(of: ":", with: "-")
        let destination = directory
            .appendingPathComponent(safeName + "-" + UUID().uuidString)
            .appendingPathExtension("json")
        try ArchiveCodec.encode(archive).write(to: destination, options: .atomic)
        return .result(dialog: "Imported \(archive.messages.count) messages. Open Message Archive to review and export them.")
    }

    private static func inboxDirectory() throws -> URL {
        let root = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        let directory = root.appendingPathComponent("ImportedConversations", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        return directory
    }
}
